var currentdatetime = new Date();

function ShowLoader() {
    jQuery('#dfm-preloader').show();
}

function HideLoader() {
    jQuery('#dfm-preloader').hide();
}

function ValidateForgotPasswordFormSubmit(formclass, label = '') {
    jQuery(document).off().on("submit", "." + formclass, function(e) {
        e.preventDefault();
        var ajax_save_form = jQuery(this);
        var formaction = ajax_save_form.attr('data-action');
        jQuery.ajax({
            enctype: 'multipart/form-data',
            url: base_url + controller + '/' + formaction,
            data: new FormData(this),
            method: 'post',
            dataType: 'json',
            processData: false,
            async: true,
            contentType: false,
            cache: false,
            timeout: 600000,
            beforeSend: function() {
                ajax_save_form.find(":submit").prop('disabled', true);
                ajax_save_form.find(":submit").html('Processing please wait...');
            },
            success: function(response) {
                ajax_save_form.find(":submit").prop('disabled', false);
                ajax_save_form.find(":submit").html(label);
                console.log("forgot response:: ", response);
                //debugger;
                if (response.status) {

                    if (response.successpopup) {
                        Swal.fire({
                            title: '',
                            html: response.message,
                            icon: '',
                            showCancelButton: false,
                            confirmButtonText: 'Okay',
                        }).then((result) => {
                            if (result.isConfirmed) {
                                window.location.reload();
                            }
                        });
                    } else {
                       // debugger;
                        window.location.reload();
                    }
                } else {

                    jQuery(".swal2-validation-message").remove('');
                    jQuery('<div class="swal2-validation-message" style="margin: 4px 0px;padding: 6px 0;">' + response.message + '</div>').insertAfter("." + formclass).fadeOut(5000);
                    //sweet_alert('Error', response.message, 'error');
                }
            }
        });
    });
}


function ValidateFormSubmit(formclass, label = '') {
    jQuery('#endingmobilenumber').html('');
    jQuery(document).off().on("submit", "." + formclass, function(e) {
        e.preventDefault();
        var ajax_save_form = jQuery(this);
        var formaction = ajax_save_form.attr('data-action');
        var getcontroller = ajax_save_form.attr('data-controller');
        if (typeof getcontroller !== 'undefined' && getcontroller !== false) {
            var ActionController = ajax_save_form.attr('data-controller');
        } else {
            var ActionController = controller;
        }
        jQuery.ajax({
            enctype: 'multipart/form-data',
            url: base_url + ActionController + '/' + formaction,
            data: new FormData(this),
            method: 'post',
            async: true,
            dataType: 'json',
            processData: false,
            contentType: false,
            cache: false,
            timeout: 600000,
            beforeSend: function() {
                ajax_save_form.find(":submit").prop('disabled', true);
                ajax_save_form.find(":submit").html('Processing please wait...');
            },
            success: function(response) {
                ajax_save_form.find(":submit").prop('disabled', false);
                ajax_save_form.find(":submit").html(label);
                if (response.status) {
                    if (response.successpopup) {
                        Swal.fire({
                            title: '',
                            html: response.message,
                            icon: '',
                            showCancelButton: false,
                            confirmButtonText: 'Okay',
                        }).then((result) => {
                            if (result.isConfirmed) {
                                if (response.http_redirect) {
                                    window.location.href = response.http_redirect;
                                } else {
                                    if (response.otpscreen) {
                                        jQuery('#endingmobilenumber').html(response.otpscreen);
                                        jQuery('.resendOTP_timermessage').show('');
                                        jQuery('.resendOTP_buttonlabel').hide('');
                                        ResentOTPTimer();
                                        UIkit.modal('#otp_regmodel').show();
                                    } else {
                                        window.location.reload();
                                    }
                                }
                            }
                        });
                    } else {
                        if (response.http_redirect) {
                            window.location.href = response.http_redirect;
                        } else {
                            if (response.otpscreen) {
                                jQuery('#endingmobilenumber').html(response.otpscreen);
                                jQuery('.resendOTP_timermessage').show('');
                                jQuery('.resendOTP_buttonlabel').hide('');
                                ResentOTPTimer();
                                UIkit.modal('#otp_regmodel').show();
                            } else {
                                window.location.reload();
                            }
                        }
                    }
                } else {
                    jQuery(".swal2-validation-message").remove('');
                    jQuery('<div class="swal2-validation-message" style="margin: 4px 0px;padding: 6px 0;">' + response.message + '</div>').insertAfter("." + formclass).fadeOut(5000);
                    //sweet_alert('Error', response.message, 'error');
                }
            }
        });
    });
}

function sweet_alert(heading, message, alert_type) {
    Swal.fire(
        heading,
        message,
        alert_type
    );
}

function ResentOTPTimer(remaining = 120) {
    var timerOn = true;
    var m = Math.floor(remaining / 60);
    var s = remaining % 60;
    m = m < 10 ? '0' + m : m;
    s = s < 10 ? '0' + s : s;
    document.getElementById('OTPTimer').innerHTML = m + ':' + s;
    remaining -= 1;
    if (remaining >= 0 && timerOn) {
        setTimeout(function() {
            ResentOTPTimer(remaining);
        }, 1000);
        return;
    }
    if (!timerOn) {
        return;
    }
    jQuery('.resendOTP_timermessage').hide('');
    jQuery('.resendOTP_buttonlabel').show('');
}
jQuery(document).ready(function() {
    var myforms = jQuery("form.uk-form-stacked");
    myforms.each(function(i) {
        var myform = myforms.eq(i);
        myform.validate({
            highlight: function(element) {
                $(element).parent().addClass('formblank-has-error');
            },
            unhighlight: function(element) {
                $(element).parent().removeClass('formblank-has-error');
            },
        });
    });
    jQuery('.resendOTPButton').on('click', function() {
        jQuery('.resendOTP_timermessage').hide('');
        jQuery('.resendOTP_buttonlabel').hide('');
        jQuery.ajax({
            enctype: 'multipart/form-data',
            url: base_url + controller + '/resendotp',
            type: "POST",
            dataType: 'json',
            async: true,
            data: { ajax: true, version: currentdatetime },
            beforeSend: function() {
                jQuery(".resendOTP_Error").html('<img src="' + base_url + 'assets/pix/ajax-loader.gif" style="margin-left: 40%;">');
                jQuery(".resendOTP").css("pointer-events", "none");
            },
            success: function(response) {
                jQuery(".resendOTP").css("pointer-events", "");
                jQuery(".resendOTP_Error").html('');
                if (response.status) {
                    Swal.fire({
                        title: '',
                        html: response.message,
                        icon: '',
                        showCancelButton: false,
                        confirmButtonText: 'Okay',
                    }).then((result) => {
                        if (result.isConfirmed) {
                            jQuery('.resendOTP_timermessage').show('');
                            jQuery('.resendOTP_buttonlabel').hide('');
                            ResentOTPTimer();
                        }
                    });
                } else {
                    sweet_alert('Error', response.message, 'error');
                }
            }
        });
    });

    jQuery('.refreshCaptchaImage').on('click', function(){
        jQuery.get(base_url+'generate-code', function(data){
            jQuery('.refreshCaptchacodeImage').html(data);
        });
    });
});